//! Largest-remainder quantization, and the degree-1 hat weights it is applied
//! to.
//!
//! Both rules are ports of `docs/site-plan/friday_clutch_check.py`, which the
//! site-plan production note requires the Friday-clutch illustration's
//! arithmetic to be generated by.  The painter on the Ticket screen drags a
//! density over the eight knots and needs the same rounding the resolution
//! weights use, so the rule lives here once and the tests below pin the exact
//! vectors that script prints.  A second rounding rule would be a second
//! semantics.
//!
//! Everything here is integer arithmetic on exact rationals with a common
//! denominator.  The Python original uses `Fraction`; the port keeps the
//! numerators and never forms a float, so "largest remainder" compares exact
//! remainders rather than two roundings of one number.

/// The illustration's payout denominator (`friday_clutch_check.py` D).
pub const PAYOUT_DENOMINATOR: u64 = 64;
/// The frozen price scale (`friday_clutch_check.py` S).
pub const PRICE_SCALE: u64 = 10_000;
/// The Friday clutch's eight knots, in cents: $100..$240 step $20.
pub const KNOT_CENTS: [u64; 8] = [
    10_000, 12_000, 14_000, 16_000, 18_000, 20_000, 22_000, 24_000,
];
/// The uniform knot gap, in cents.
pub const KNOT_GAP_CENTS: u64 = 2_000;

/// Canonical largest-remainder quantization with lowest-index ties.
///
/// `weights` are exact nonnegative shares in *any* common unit; the result
/// sums to `total` exactly.  Ties on the fractional remainder are broken by
/// the lower index, which is the repository's canonical rule (PROJECT.md §6)
/// and the one `friday_clutch_check.py` implements.
///
/// Returns `None` only when every weight is zero, where no share is defined.
#[must_use]
pub fn largest_remainder(weights: &[u64], total: u64) -> Option<Vec<u64>> {
    let sum: u128 = weights.iter().map(|value| u128::from(*value)).sum();
    if sum == 0 {
        return None;
    }
    let total = u128::from(total);
    let mut floors = Vec::with_capacity(weights.len());
    let mut remainders = Vec::with_capacity(weights.len());
    for weight in weights {
        let exact = u128::from(*weight) * total;
        floors.push(exact / sum);
        remainders.push(exact % sum);
    }
    let assigned: u128 = floors.iter().sum();
    let mut deficit = total.saturating_sub(assigned);
    // Descending remainder, ascending index: `sort_by` is stable, so sorting
    // the already-ascending index order by remainder alone leaves ties in
    // index order.
    let mut order: Vec<usize> = (0..weights.len()).collect();
    order.sort_by(|left, right| remainders[*right].cmp(&remainders[*left]));
    for index in order {
        if deficit == 0 {
            break;
        }
        floors[index] += 1;
        deficit -= 1;
    }
    Some(
        floors
            .into_iter()
            .map(|value| u64::try_from(value).unwrap_or(u64::MAX))
            .collect(),
    )
}

/// Degree-1 open-clamped hat weights at `cents`, as exact numerators over
/// [`KNOT_GAP_CENTS`].
///
/// Partition of unity is the whole content of the basis the relation sees, so
/// the numerators sum to the gap exactly — asserted by the caller-visible
/// `debug_assert` below rather than left to the reader.  A point at or beyond
/// an end knot clamps onto that knot, which is EDGE-CLAMP-01.
#[must_use]
pub fn hat_numerators(cents: u64) -> [u64; 8] {
    let mut out = [0_u64; 8];
    if cents <= KNOT_CENTS[0] {
        out[0] = KNOT_GAP_CENTS;
        return out;
    }
    if cents >= KNOT_CENTS[7] {
        out[7] = KNOT_GAP_CENTS;
        return out;
    }
    for index in 0..7 {
        let (left, right) = (KNOT_CENTS[index], KNOT_CENTS[index + 1]);
        if cents >= left && cents <= right {
            out[index + 1] = cents - left;
            out[index] = right - cents;
            break;
        }
    }
    debug_assert_eq!(out.iter().sum::<u64>(), KNOT_GAP_CENTS);
    out
}

/// The quantized resolution weight vector at `cents`: hats, then largest
/// remainder onto [`PAYOUT_DENOMINATOR`].
#[must_use]
pub fn resolution_weights(cents: u64) -> Vec<u64> {
    let numerators = hat_numerators(cents);
    largest_remainder(&numerators, PAYOUT_DENOMINATOR).unwrap_or_else(|| vec![0; 8])
}

/// A painted belief, quantized onto the price simplex in `step` units.
///
/// The order plane admits a single-Egg limit only when it is an exact member
/// of the frozen tick vector, so a painted number that is not on the ladder
/// cannot be quoted.  Quantizing the belief itself in ladder units — rather
/// than quantizing to the scale and then snapping each limit — is what keeps
/// the quoted vector both on the ladder *and* summing to the price scale, so
/// the midpoint of two such vectors is a valid price vector by construction.
///
/// `weights` are the dragged numbers in any unit; the result is in price
/// units, every entry a multiple of `step`, summing to [`PRICE_SCALE`].
#[must_use]
pub fn belief_on_ladder(weights: &[u64], step: u64) -> Option<Vec<u64>> {
    if step == 0 || !PRICE_SCALE.is_multiple_of(step) {
        return None;
    }
    let units = largest_remainder(weights, PRICE_SCALE / step)?;
    Some(units.into_iter().map(|value| value * step).collect())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The pin `friday_clutch_check.py` prints: the illustration resolves at
    /// $163.40 and the quantized weight vector is exactly this.
    #[test]
    fn the_illustrations_resolution_weights_are_the_scripts_vector() {
        assert_eq!(resolution_weights(16_340), vec![0, 0, 0, 53, 11, 0, 0, 0]);
        assert_eq!(resolution_weights(16_340).iter().sum::<u64>(), 64);
    }

    /// The exact rational the script checks before it rounds: the weight at
    /// the $160 knot is 64 * (18000 - 16340) / 2000.
    #[test]
    fn the_exact_hat_numerators_are_the_scripts_fraction() {
        let numerators = hat_numerators(16_340);
        assert_eq!(numerators[3], 18_000 - 16_340);
        assert_eq!(numerators[4], 16_340 - 16_000);
        assert_eq!(numerators.iter().sum::<u64>(), KNOT_GAP_CENTS);
    }

    #[test]
    fn a_point_on_a_knot_puts_the_whole_weight_there() {
        assert_eq!(resolution_weights(16_000), vec![0, 0, 0, 64, 0, 0, 0, 0]);
        assert_eq!(resolution_weights(10_000), vec![64, 0, 0, 0, 0, 0, 0, 0]);
    }

    /// EDGE-CLAMP-01: outside the grid clamps onto the end knot rather than
    /// extrapolating.
    #[test]
    fn points_outside_the_grid_clamp_onto_the_end_knots() {
        assert_eq!(resolution_weights(1), vec![64, 0, 0, 0, 0, 0, 0, 0]);
        assert_eq!(resolution_weights(99_999), vec![0, 0, 0, 0, 0, 0, 0, 64]);
    }

    /// A tie on the remainder goes to the lower index, which is what makes
    /// the rule canonical rather than dependent on a sort's stability.
    #[test]
    fn ties_break_to_the_lower_index() {
        assert_eq!(largest_remainder(&[1, 1, 1], 4), Some(vec![2, 1, 1]));
        assert_eq!(largest_remainder(&[1, 1, 1, 1], 6), Some(vec![2, 2, 1, 1]));
    }

    #[test]
    fn a_quantization_always_sums_to_the_total() {
        for total in [7_u64, 64, 50, 10_000] {
            let out = largest_remainder(&[3, 1, 4, 1, 5, 9, 2, 6], total).expect("nonzero");
            assert_eq!(out.iter().sum::<u64>(), total);
        }
    }

    #[test]
    fn an_all_zero_belief_has_no_share_to_quantize() {
        assert_eq!(largest_remainder(&[0, 0, 0], 64), None);
    }

    /// The bot's published belief, put on the 200-unit ladder: still a price
    /// vector, now quotable.
    #[test]
    fn the_published_belief_lands_on_the_ladder_and_still_sums_to_scale() {
        let belief = [0_u64, 127, 2_662, 5_945, 1_266, 0, 0, 0];
        let quoted = belief_on_ladder(&belief, 200).expect("nonzero belief");
        assert_eq!(quoted, vec![0, 200, 2_600, 6_000, 1_200, 0, 0, 0]);
        assert_eq!(quoted.iter().sum::<u64>(), PRICE_SCALE);
        assert!(quoted.iter().all(|value| value % 200 == 0));
    }

    /// The midpoint of two ladder vectors is a price vector on the simplex —
    /// the property the auto-crank's candidate depends on.
    #[test]
    fn the_midpoint_of_two_ladder_beliefs_is_on_the_simplex() {
        let one = belief_on_ladder(&[0, 127, 2_662, 5_945, 1_266, 0, 0, 0], 200).expect("a");
        let two =
            belief_on_ladder(&[100, 400, 1_500, 3_300, 2_700, 1_300, 500, 200], 200).expect("b");
        let mid: Vec<u64> = one
            .iter()
            .zip(&two)
            .map(|(left, right)| (left + right) / 2)
            .collect();
        assert_eq!(mid.iter().sum::<u64>(), PRICE_SCALE);
        for index in 0..8 {
            let low = one[index].min(two[index]);
            let high = one[index].max(two[index]);
            assert!(mid[index] >= low && mid[index] <= high);
        }
    }

    #[test]
    fn a_ladder_step_that_does_not_divide_the_scale_is_refused() {
        assert!(belief_on_ladder(&[1, 1], 3).is_none());
        assert!(belief_on_ladder(&[1, 1], 0).is_none());
    }
}
